#include <stdlib.h>
#include <stdio.h>
#include <unistd.h>
int main ()
{
int x, y, z;
int pid;
  x = 5;
  y = 10;
  z = x*x + y*y;
  printf("parent process : x = %d, y = %d, z = %d\n", x, y, z);
  /* Fork a child process.  */
  pid = fork ();
  if (pid == (pid_t) 0) {
    x = x + 3;
    y = y - 3;
    z = x*x + y*y;
    printf("child process : x = %d, y = %d, z = %d\n", x, y, z);
  }
  else {
    x = x - 2;
    y = y - 5;
    z = x*x + y*y;
    printf("parent process : x = %d, y = %d, z = %d\n", x, y, z);
  }
  return 0;
}

